import { test } from '@playwright/test'
import { opGoto, opClick, opFill, opPress, opSeen } from './prims'

test('@journey:negative @smoke Rejects empty contact form submission', async ({ page }) => {
  await opGoto(page, '/contact')
  await opClick(page, 'combobox', 'Which service are you interested in')
  await opClick(page, 'option', 'Test Automation')
  await opFill(page, 'Name', '')
  await opFill(page, 'Email', '')
  await opFill(page, 'Message', '')
  await opClick(page, 'button', 'Submit')
  await opSeen(page, 'alert', 'Please fill out all required fields.')
})
